def find_rectangular_blocks(grid, target_color, bg_color=0):
    """Find rectangular blocks of target_color."""
    blocks = []
    visited = set()

    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if grid[r][c] == target_color and (r, c) not in visited:
                # Find extent of this rectangle
                top, left = r, c
                while r+1 < len(grid) and grid[r+1][c] == target_color:
                    r += 1
                    top = r
                while c+1 < len(grid[r]) and grid[top][c+1] == target_color:
                    c += 1
                    left = c
                # Check if it's rectangular
